const results = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n -i \"beep|audio|sound|tone|oscillator|match|pair\" src README.md", max_output_tokens:8000}),
  tools.exec_command({cmd:"find .. -name AGENTS.md -print", max_output_tokens:2000}),
  tools.exec_command({cmd:"ls -la && cat package.json", max_output_tokens:5000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

